==== booking.ts
     1	import { Injectable } from '@angular/core';
     2	
     3	/** A seat (`start === end`) or a couch (`end === start + 1`) within one row. */
     4	export interface SelectedUnit {
     5	  row: number;
     6	  start: number;
     7	  end: number;
     8	}
     9	
    10	/** Values typed into the checkout form (section 7.1). */
    11	export interface CheckoutValues {
    12	  firstName: string;
    13	  lastName: string;
    14	  email: string;
    15	  confirmEmail: string;
    16	  phone: string;
    17	  terms: boolean;
    18	}
    19	
    20	/** The booking in progress (section 3.1), kept in sessionStorage. */
    21	export interface Booking {
    22	  screeningId: number;
    23	  units: SelectedUnit[];
    24	  /** Checkout form values, saved as they are typed; absent until the form is used. */
    25	  checkout?: CheckoutValues;
    26	  /** Email address of the customer once the booking is paid. */
    27	  paidEmail?: string;
    28	}
    29	
    30	const STORAGE_KEY = 'cinescope.booking';
    31	
    32	export function unitKey(row: number, start: number): string {
    33	  return `${row}:${start}`;
    34	}
    35	
    36	/** Seat identifiers `R<row>C<column>` of a unit; a couch gives both of its identifiers (section 2.1). */
    37	export function seatIdentifiers(unit: SelectedUnit): string[] {
    38	  const identifiers: string[] = [];
    39	  for (let column = unit.start; column <= unit.end; column++) {
    40	    identifiers.push(`R${unit.row}C${column}`);
    41	  }
    42	  return identifiers;
    43	}
    44	
    45	/** Orders units by row, then by column. */
    46	export function sortUnits(units: readonly SelectedUnit[]): SelectedUnit[] {
    47	  return [...units].sort((a, b) => a.row - b.row || a.start - b.start);
    48	}
    49	
    50	/** `Couch <a>-<b>` for a couch, the column number for a single seat (AC-37). */
    51	export function describeSeat(unit: SelectedUnit): string {
    52	  return unit.start === unit.end ? `${unit.start}` : `Couch ${unit.start}-${unit.end}`;
    53	}
    54	
    55	/** Reads and writes the booking in sessionStorage, so it survives a reload. */
    56	@Injectable({ providedIn: 'root' })
    57	export class BookingStore {
    58	  read(): Booking | null {
    59	    const raw = sessionStorage.getItem(STORAGE_KEY);
    60	    if (!raw) {
    61	      return null;
    62	    }
    63	    try {
    64	      const booking = JSON.parse(raw) as Booking;
    65	      return typeof booking?.screeningId === 'number' && Array.isArray(booking.units) ? booking : null;
    66	    } catch {
    67	      return null;
    68	    }
    69	  }
    70	
    71	  write(booking: Booking): void {
    72	    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    73	  }
    74	
    75	  /** Merges `change` into the booking in progress, keeping the other fields; does nothing without one. */
    76	  update(change: Partial<Booking>): void {
    77	    const current = this.read();
    78	    if (current) {
    79	      this.write({ ...current, ...change });
    80	    }
    81	  }
    82	
    83	  clear(): void {
    84	    sessionStorage.removeItem(STORAGE_KEY);
    85	  }
    86	}
==== booking-guard.ts
     1	import { inject } from '@angular/core';
     2	import { CanActivateFn, Router } from '@angular/router';
     3	import { BookingStore } from './booking';
     4	
     5	/**
     6	 * Lets a route for screening `:id` open only while the booking is unpaid, holds seats and belongs
     7	 * to that screening (section 3.1). Otherwise redirects to the movie list. Runs on every entry,
     8	 * including reloads.
     9	 */
    10	export const bookingGuard: CanActivateFn = (route) => {
    11	  const booking = inject(BookingStore).read();
    12	  const screeningId = Number(route.paramMap.get('id'));
    13	  const allowed =
    14	    booking !== null &&
    15	    booking.screeningId === screeningId &&
    16	    booking.units.length > 0 &&
    17	    booking.paidEmail === undefined;
    18	  return allowed ? true : inject(Router).createUrlTree(['/']);
    19	};
    20	
    21	/** Lets the confirmation open only once the booking is paid (section 3.1). Otherwise redirects to the movie list. */
    22	export const paidBookingGuard: CanActivateFn = () => {
    23	  const booking = inject(BookingStore).read();
    24	  return booking?.paidEmail !== undefined ? true : inject(Router).createUrlTree(['/']);
    25	};
==== date-utils.ts
     1	const WEEKDAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
     2	
     3	/** Local midnight of the given date. */
     4	export function startOfDay(date: Date): Date {
     5	  return new Date(date.getFullYear(), date.getMonth(), date.getDate());
     6	}
     7	
     8	export function addDays(date: Date, days: number): Date {
     9	  return new Date(date.getFullYear(), date.getMonth(), date.getDate() + days);
    10	}
    11	
    12	/** Formats a date as an ISO date (YYYY-MM-DD) using local calendar fields. */
    13	export function toIsoDate(date: Date): string {
    14	  const y = String(date.getFullYear()).padStart(4, '0');
    15	  const m = String(date.getMonth() + 1).padStart(2, '0');
    16	  const d = String(date.getDate()).padStart(2, '0');
    17	  return `${y}-${m}-${d}`;
    18	}
    19	
    20	/** Parses a strict YYYY-MM-DD string into a local date; returns null for anything invalid. */
    21	export function parseIsoDate(value: string | null | undefined): Date | null {
    22	  if (!value || !/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    23	    return null;
    24	  }
    25	  const [y, m, d] = value.split('-').map(Number);
    26	  const date = new Date(y, m - 1, d);
    27	  // Rejects overflowing values such as 2026-02-30.
    28	  return toIsoDate(date) === value ? date : null;
    29	}
    30	
    31	export function englishWeekday(date: Date): string {
    32	  return WEEKDAYS[date.getDay()];
    33	}
    34	
    35	const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    36	
    37	/** Show date `<Weekday> <D> <Mon> <HH:mm>`, e.g. `Tuesday 15 Sep 16:00`. */
    38	export function formatShowDate(isoDate: string, time: string): string {
    39	  const date = parseIsoDate(isoDate);
    40	  if (!date) {
    41	    return `${isoDate} ${time}`;
    42	  }
    43	  return `${englishWeekday(date)} ${date.getDate()} ${MONTHS[date.getMonth()]} ${time}`;
    44	}
