    11	/** Loads a screening together with its movie. Errors are passed on to the caller. */
    12	@Injectable({ providedIn: 'root' })
    13	export class ScreeningLoader {
    14	  private readonly http = inject(HttpClient);
    15	
    16	  load(id: string): Observable<LoadedScreening> {
    17	    return this.http.get<Screening>(`${API_BASE_URL}/screenings/${id}`).pipe(
    18	      switchMap((screening) =>
    19	        this.http
    20	          .get<Movie>(`${API_BASE_URL}/movies/${screening.movieId}`)
    21	          .pipe(map((movie) => ({ screening, movie }))),
    22	      ),
    23	    );
    24	  }
    25	}
