     7	import { ActivatedRoute, Router } from '@angular/router';
     8	import { HttpClient } from '@angular/common/http';
     9	import { forkJoin, map } from 'rxjs';
    10	import { addDays, englishWeekday, parseIsoDate, startOfDay, toIsoDate } from '../date-utils';
    11	import { API_BASE_URL, Movie, Screening } from '../models';
    12	
    13	interface DayOption {
    14	  iso: string;
    15	  label: string;
    16	}
    17	
    18	interface MovieCard {
    19	  movie: Movie;
    20	  screenings: Screening[];
    21	}
    22	
    23	type LoadState =
    24	  | { status: 'loading' }
    25	  | { status: 'error' }
    26	  | { status: 'loaded'; movies: Movie[]; screenings: Screening[] };
    27	
    28	@Component({
    29	  selector: 'app-movie-list',
    30	  imports: [MatButtonModule, MatDatepickerModule, MatFormFieldModule, MatInputModule],
    31	  templateUrl: './movie-list.html',
    32	  styleUrl: './movie-list.scss',
    33	})
    34	export class MovieList {
    35	  private readonly http = inject(HttpClient);
    36	  private readonly router = inject(Router);
    37	  private readonly route = inject(ActivatedRoute);
    38	
    39	  private readonly today = startOfDay(new Date());
    40	  protected readonly todayIso = toIsoDate(this.today);
    41	  protected readonly todayDate = this.today;
    42	
    43	  /** Today and the next four days; the first is labelled `Today`. */
    44	  protected readonly days: DayOption[] = Array.from({ length: 5 }, (_, offset) => {
    45	    const date = addDays(this.today, offset);
    46	    return { iso: toIsoDate(date), label: offset === 0 ? 'Today' : englishWeekday(date) };
    47	  });
    48	
    49	  private readonly queryDate = toSignal(
    50	    this.route.queryParamMap.pipe(map((params) => params.get('date'))),
    51	    { initialValue: null },
    52	  );
    53	
    54	  /** The selected day; a missing, invalid or past `date` selects today. */
    55	  protected readonly selectedIso = computed(() => {
    56	    const requested = this.queryDate();
    57	    if (requested && parseIsoDate(requested) && requested >= this.todayIso) {
    58	      return requested;
    59	    }
    60	    return this.todayIso;
    61	  });
    62	
    63	  /** The day chosen in the datepicker, shown only when it is not one of the five day buttons. */
    64	  protected readonly pickedDate = computed(() => {
    65	    const iso = this.selectedIso();
    66	    return this.days.some((day) => day.iso === iso) ? null : parseIsoDate(iso);
    67	  });
    68	
    69	  protected readonly state = signal<LoadState>({ status: 'loading' });
    70	
    71	  /** Movies with at least one screening on the selected day, in backend order. */
    72	  protected readonly cards = computed<MovieCard[]>(() => {
    73	    const state = this.state();
    74	    if (state.status !== 'loaded') {
    75	      return [];
    76	    }
    77	    const date = this.selectedIso();
    78	    const onDay = state.screenings.filter((screening) => screening.date === date);
    79	    return state.movies.flatMap((movie) => {
    80	      const screenings = onDay
    81	        .filter((screening) => screening.movieId === movie.id)
    82	        .sort((a, b) => a.time.localeCompare(b.time));
    83	      return screenings.length > 0 ? [{ movie, screenings }] : [];
    84	    });
    85	  });
    86	
    87	  constructor() {
    88	    this.load();
    89	  }
    90	
    91	  protected load(): void {
    92	    this.state.set({ status: 'loading' });
    93	    forkJoin({
    94	      movies: this.http.get<Movie[]>(`${API_BASE_URL}/movies`),
    95	      screenings: this.http.get<Screening[]>(`${API_BASE_URL}/screenings`),
    96	    }).subscribe({
    97	      next: (data) => this.state.set({ status: 'loaded', ...data }),
    98	      error: () => this.state.set({ status: 'error' }),
    99	    });
   100	  }
   101	
   102	  protected selectDay(iso: string): void {
   103	    this.router.navigate(['/'], { queryParams: { date: iso } });
   104	  }
   105	
   106	  protected onDatePicked(date: Date | null): void {
   107	    if (date) {
   108	      this.selectDay(toIsoDate(date));
   109	    }
   110	  }
   111	
   112	  protected openSeats(screeningId: number): void {
   113	    this.router.navigate(['/screenings', screeningId, 'seats']);
   114	  }
   115	}
