==== seat-selection/auditorium.ts
     1	export type SeatState = 'available' | 'unavailable' | 'accessible';
     2	
     3	/**
     4	 * One element of a row: a seat, a couch, or an empty gap (`aisle` or `entrance`).
     5	 * Gaps carry no columns and no state.
     6	 */
     7	export interface AuditoriumCell {
     8	  type: 'seat' | 'couch' | 'aisle' | 'entrance';
     9	  /** First column covered by the cell; 0 for gaps. */
    10	  start: number;
    11	  /** Last column covered by the cell; equal to `start` for a seat, `start + 1` for a couch. */
    12	  end: number;
    13	  /** Seat or couch state; null for gaps. A couch is never `accessible`. */
    14	  state: SeatState | null;
    15	}
    16	
    17	export interface AuditoriumRow {
    18	  number: number;
    19	  cells: AuditoriumCell[];
    20	}
    21	
    22	const ROW_COUNT = 15;
    23	const COUCH_ROW = 15;
    24	const LAST_ENTRANCE_ROW = 10;
    25	const ACCESSIBLE_ROW = 1;
    26	const ACCESSIBLE_FIRST_COLUMN = 10;
    27	const ACCESSIBLE_LAST_COLUMN = 15;
    28	
    29	/**
    30	 * Builds the 15 rows of the auditorium. Every row is made of the same blocks — columns 1–4,
    31	 * an aisle, columns 5–20, an aisle, columns 21–24 — so columns line up across rows. In rows
    32	 * 1–10 the first block is replaced by an empty entrance of the same width.
    33	 *
    34	 * @param occupied seat identifiers (`R<row>C<column>`) that are already sold
    35	 */
    36	export function buildAuditorium(occupied: ReadonlySet<string>): AuditoriumRow[] {
    37	  return Array.from({ length: ROW_COUNT }, (_, index) => {
    38	    const row = index + 1;
    39	    const cells: AuditoriumCell[] = [
    40	      ...(row <= LAST_ENTRANCE_ROW ? [gap('entrance')] : block(row, 1, 4, occupied)),
    41	      gap('aisle'),
    42	      ...block(row, 5, 20, occupied),
    43	      gap('aisle'),
    44	      ...block(row, 21, 24, occupied),
    45	    ];
    46	    return { number: row, cells };
    47	  });
    48	}
    49	
    50	function gap(type: 'aisle' | 'entrance'): AuditoriumCell {
    51	  return { type, start: 0, end: 0, state: null };
    52	}
    53	
    54	/** Seats of a block in a regular row; couches of a block in the couch row. */
    55	function block(row: number, first: number, last: number, occupied: ReadonlySet<string>): AuditoriumCell[] {
    56	  const cells: AuditoriumCell[] = [];
    57	  if (row === COUCH_ROW) {
    58	    for (let column = first; column <= last; column += 2) {
