   138	      return;
   139	    }
   140	    const values = this.form.getRawValue();
   141	    const body: NewReservation = {
   142	      screeningId: booking.screeningId,
   143	      seats: sortUnits(booking.units).flatMap(seatIdentifiers),
   144	      customer: {
   145	        firstName: values.firstName,
   146	        lastName: values.lastName,
   147	        email: values.email,
   148	        phone: values.phone,
   149	      },
   150	      totalPrice: this.total,
   151	    };
   152	
   153	    this.submitting.set(true);
   154	    this.http.post<Reservation>(`${API_BASE_URL}/reservations`, body).subscribe({
   155	      next: () => {
   156	        this.booking.update({ paidEmail: values.email });
   157	        this.router.navigate(['/confirmation']);
   158	      },
   159	      error: () => {
   160	        this.submitting.set(false);
   161	        this.toast.show(PAYMENT_FAILED_MESSAGE);
   162	      },
   163	    });
   164	  }
   165	}
