    expect(all('day-picker').length).toBe(1);
    expect(all('date-picker').length).toBe(1);
    expect(all('movie-card').map((e) => e.getAttribute('data-movie-id'))).toEqual(['1', '2']);
    expect(texts('movie-title')).toEqual(['The Silent Harbor', 'Neon Circuit']);
    expect(texts('movie-genre')).toEqual(['Drama', 'Sci-Fi']);
    expect(texts('movie-runtime')).toEqual(['128 min', '142 min']);
    expect(texts('movie-format')).toEqual(['PL subtitles', 'PL dubbing']);
    expect(texts('screening-button')).toEqual(['16:00', '19:30', '15:00']);
    expect(all('screening-button').map((e) => e.getAttribute('data-screening-id'))).toEqual(['20', '21', '22']);
  });

  it('shows the error state and retries', () => {
    http.expectOne(`${API}/movies`).flush('x', { status: 500, statusText: 'err' });
    http.expectOne(`${API}/screenings`).flush([]);
    fixture.detectChanges();
    expect(texts('movies-error')).toEqual(['Failed to load movies']);
    (all('movies-retry-button')[0] as HTMLElement).click();
    fixture.detectChanges();
    expect(all('movies-loading').length).toBe(1);
    http.expectOne(`${API}/movies`).flush([MOVIE]);
    http.expectOne(`${API}/screenings`).flush(SCREENINGS);
    fixture.detectChanges();
    expect(all('movie-card').length).toBe(1);
  });

  it('shows the empty state for a day without screenings', () => {
    http.expectOne(`${API}/movies`).flush([MOVIE, MOVIE2]);
    http.expectOne(`${API}/screenings`).flush([SCREENINGS[3]]);
    fixture.detectChanges();
    expect(texts('movies-empty')).toEqual(['No screenings on this day']);
    expect(all('movie-card').length).toBe(0);
  });
});

