    (root.querySelector('[data-testid="confirmation-continue-button"]') as HTMLElement).click();
    expect(sessionStorage.getItem('cinescope.booking')).toBeNull();
    expect(navigate).toHaveBeenCalledWith(['/']);
  });

  it('guards the routes', () => {
