    const route = (id: string) => ({ paramMap: convertToParamMap({ id }) }) as never;
    const run = (fn: () => unknown) => TestBed.runInInjectionContext(fn);
    const isRedirect = (r: unknown) => r instanceof UrlTree;

    setBooking(null);
    expect(isRedirect(run(() => bookingGuard(route('1'), {} as never)))).toBe(true);
    setBooking(TWO_UNITS);
    expect(run(() => bookingGuard(route('1'), {} as never))).toBe(true);
    expect(isRedirect(run(() => bookingGuard(route('2'), {} as never)))).toBe(true);
    setBooking({ screeningId: 1, units: [] });
    expect(isRedirect(run(() => bookingGuard(route('1'), {} as never)))).toBe(true);
    setBooking({ ...TWO_UNITS, paidEmail: 'a@b.co' });
    expect(isRedirect(run(() => bookingGuard(route('1'), {} as never)))).toBe(true);
    expect(isRedirect(run(() => paidBookingGuard({} as never, {} as never)))).toBe(false);
    setBooking(TWO_UNITS);
    expect(isRedirect(run(() => paidBookingGuard({} as never, {} as never)))).toBe(true);
  });
});

